package mrpapermoon.whisper.service.internalimport com.google.android.gms.nearby.connection.ConnectionInfoimport com.google.android.gms.nearby.connection.DiscoveredEndpointInfoimport com.google.android.gms.nearby.connection.PayloadTransferUpdateinternal fun ConnectionInfo.dumpString(): String = "ConnectionInfo(endpointName=$endpointName, isIncomingConnection=$isIncomingConnection)"internal fun DiscoveredEndpointInfo.dumpString(): String = "DiscoveredEndpointInfo(serviceId: $serviceId, endpointName: $endpointName)"internal fun PayloadTransferUpdate.dumpString(): String = "PayloadTransferUpdate(payloadId=$payloadId, status=$status, bytesTransferred=$bytesTransferred, totalBytes=$totalBytes)"